"use strict";

/* ============================================================
 * Browser CAD editor.
 * World coordinates are y-up (CAD convention); screen is y-down.
 * Entities: line, rect, circle, arc, polyline, text, dim.
 * ============================================================ */

// ---------- document state ----------
let doc = {
  layers: [{ name: "0", color: "#d6dade", visible: true }],
  activeLayer: "0",
  entities: [],
};
let nextId = 1;

const undoStack = [];
const redoStack = [];
const UNDO_MAX = 100;

// ---------- view state ----------
const view = { x: 0, y: 0, scale: 1 }; // world coords of bottom-left-ish origin, px per unit
let canvasW = 0, canvasH = 0;

// ---------- interaction state ----------
let tool = "select";
let toolPts = [];          // committed points of in-progress entity
let cursorWorld = { x: 0, y: 0 };
let snapResult = null;     // {x, y, kind} or null
let snapGrid = true;
let snapObj = true;
let selection = new Set(); // entity ids
let drag = null;           // {kind:'pan'|'move'|'rubber', ...}
let spaceDown = false;
let shiftDown = false;

// ---------- DOM ----------
const canvas = document.getElementById("canvas");
const ctx = canvas.getContext("2d");
const $ = (id) => document.getElementById(id);

// ============================================================
// Coordinate transforms
// ============================================================
function w2sX(wx) { return (wx - view.x) * view.scale; }
function w2sY(wy) { return canvasH - (wy - view.y) * view.scale; }
function s2wX(sx) { return sx / view.scale + view.x; }
function s2wY(sy) { return (canvasH - sy) / view.scale + view.y; }
function w2s(p) { return { x: w2sX(p.x), y: w2sY(p.y) }; }

// ============================================================
// Geometry helpers
// ============================================================
function dist(a, b) { return Math.hypot(a.x - b.x, a.y - b.y); }

function distToSegment(p, a, b) {
  const dx = b.x - a.x, dy = b.y - a.y;
  const len2 = dx * dx + dy * dy;
  let t = len2 ? ((p.x - a.x) * dx + (p.y - a.y) * dy) / len2 : 0;
  t = Math.max(0, Math.min(1, t));
  return Math.hypot(p.x - (a.x + t * dx), p.y - (a.y + t * dy));
}

function normAngle(a) { // -> [0, 2PI)
  a %= 2 * Math.PI;
  return a < 0 ? a + 2 * Math.PI : a;
}

// Sweep from a0 to angle `a` in the arc's direction, in [0, 2PI)
function sweepTo(arc, a) {
  const d = normAngle(arc.ccw ? a - arc.a0 : arc.a0 - a);
  return d;
}
function arcSweep(arc) { return sweepTo(arc, arc.a1) || 2 * Math.PI; }
function angleOnArc(arc, a) { return sweepTo(arc, a) <= arcSweep(arc) + 1e-9; }
function arcPoint(arc, a) {
  return { x: arc.cx + arc.r * Math.cos(a), y: arc.cy + arc.r * Math.sin(a) };
}

// Circumcircle of three points; null if collinear.
function circumcircle(p1, p2, p3) {
  const d = 2 * (p1.x * (p2.y - p3.y) + p2.x * (p3.y - p1.y) + p3.x * (p1.y - p2.y));
  if (Math.abs(d) < 1e-12) return null;
  const s1 = p1.x * p1.x + p1.y * p1.y;
  const s2 = p2.x * p2.x + p2.y * p2.y;
  const s3 = p3.x * p3.x + p3.y * p3.y;
  const cx = (s1 * (p2.y - p3.y) + s2 * (p3.y - p1.y) + s3 * (p1.y - p2.y)) / d;
  const cy = (s1 * (p3.x - p2.x) + s2 * (p1.x - p3.x) + s3 * (p2.x - p1.x)) / d;
  return { cx, cy, r: Math.hypot(p1.x - cx, p1.y - cy) };
}

// Arc through start p1, end p2, passing through p3.
function arcFrom3Points(p1, p2, p3) {
  const c = circumcircle(p1, p2, p3);
  if (!c) return null;
  const a0 = Math.atan2(p1.y - c.cy, p1.x - c.cx);
  const a1 = Math.atan2(p2.y - c.cy, p2.x - c.cx);
  const am = Math.atan2(p3.y - c.cy, p3.x - c.cx);
  const ccw = normAngle(am - a0) < normAngle(a1 - a0);
  return { cx: c.cx, cy: c.cy, r: c.r, a0, a1, ccw };
}

// ============================================================
// Entity model
// ============================================================
function entityColor(e) {
  if (e.color) return e.color;
  const layer = doc.layers.find((l) => l.name === e.layer);
  return layer ? layer.color : "#d6dade";
}

function layerVisible(name) {
  const l = doc.layers.find((l) => l.name === name);
  return !l || l.visible;
}

function polySegments(e) { // rect & polyline -> list of [a, b]
  let pts;
  if (e.type === "rect") {
    pts = [
      { x: e.x, y: e.y }, { x: e.x + e.w, y: e.y },
      { x: e.x + e.w, y: e.y + e.h }, { x: e.x, y: e.y + e.h },
    ];
  } else {
    pts = e.pts;
  }
  const segs = [];
  const n = pts.length;
  const last = (e.type === "rect" || e.closed) ? n : n - 1;
  for (let i = 0; i < last; i++) segs.push([pts[i], pts[(i + 1) % n]]);
  return segs;
}

function dimGeometry(e) {
  const dx = e.x2 - e.x1, dy = e.y2 - e.y1;
  const len = Math.hypot(dx, dy) || 1;
  const nx = -dy / len, ny = dx / len; // unit normal
  const q1 = { x: e.x1 + nx * e.off, y: e.y1 + ny * e.off };
  const q2 = { x: e.x2 + nx * e.off, y: e.y2 + ny * e.off };
  return { q1, q2, nx, ny, len };
}

function textBBox(e) {
  const w = e.text.length * e.size * 0.6;
  return { minX: e.x, minY: e.y, maxX: e.x + w, maxY: e.y + e.size };
}

function entityBBox(e) {
  switch (e.type) {
    case "line":
      return {
        minX: Math.min(e.x1, e.x2), minY: Math.min(e.y1, e.y2),
        maxX: Math.max(e.x1, e.x2), maxY: Math.max(e.y1, e.y2),
      };
    case "rect":
      return { minX: e.x, minY: e.y, maxX: e.x + e.w, maxY: e.y + e.h };
    case "circle":
      return { minX: e.cx - e.r, minY: e.cy - e.r, maxX: e.cx + e.r, maxY: e.cy + e.r };
    case "arc": {
      const pts = [arcPoint(e, e.a0), arcPoint(e, e.a1)];
      // include axis-extreme points that lie on the arc
      for (const a of [0, Math.PI / 2, Math.PI, 3 * Math.PI / 2]) {
        if (angleOnArc(e, a)) pts.push(arcPoint(e, a));
      }
      return {
        minX: Math.min(...pts.map((p) => p.x)), minY: Math.min(...pts.map((p) => p.y)),
        maxX: Math.max(...pts.map((p) => p.x)), maxY: Math.max(...pts.map((p) => p.y)),
      };
    }
    case "polyline":
      return {
        minX: Math.min(...e.pts.map((p) => p.x)), minY: Math.min(...e.pts.map((p) => p.y)),
        maxX: Math.max(...e.pts.map((p) => p.x)), maxY: Math.max(...e.pts.map((p) => p.y)),
      };
    case "text":
      return textBBox(e);
    case "dim": {
      const g = dimGeometry(e);
      const xs = [e.x1, e.x2, g.q1.x, g.q2.x];
      const ys = [e.y1, e.y2, g.q1.y, g.q2.y];
      return { minX: Math.min(...xs), minY: Math.min(...ys), maxX: Math.max(...xs), maxY: Math.max(...ys) };
    }
  }
}

function hitTest(e, p, tol) {
  switch (e.type) {
    case "line":
      return distToSegment(p, { x: e.x1, y: e.y1 }, { x: e.x2, y: e.y2 }) < tol;
    case "rect":
    case "polyline":
      return polySegments(e).some(([a, b]) => distToSegment(p, a, b) < tol);
    case "circle":
      return Math.abs(dist(p, { x: e.cx, y: e.cy }) - e.r) < tol;
    case "arc": {
      if (Math.abs(dist(p, { x: e.cx, y: e.cy }) - e.r) >= tol) return false;
      return angleOnArc(e, Math.atan2(p.y - e.cy, p.x - e.cx));
    }
    case "text": {
      const b = textBBox(e);
      return p.x >= b.minX - tol && p.x <= b.maxX + tol && p.y >= b.minY - tol && p.y <= b.maxY + tol;
    }
    case "dim": {
      const g = dimGeometry(e);
      return (
        distToSegment(p, g.q1, g.q2) < tol ||
        distToSegment(p, { x: e.x1, y: e.y1 }, g.q1) < tol ||
        distToSegment(p, { x: e.x2, y: e.y2 }, g.q2) < tol
      );
    }
  }
  return false;
}

// Object-snap candidate points: {x, y, kind}
function snapPoints(e) {
  switch (e.type) {
    case "line":
      return [
        { x: e.x1, y: e.y1, kind: "end" },
        { x: e.x2, y: e.y2, kind: "end" },
        { x: (e.x1 + e.x2) / 2, y: (e.y1 + e.y2) / 2, kind: "mid" },
      ];
    case "rect": {
      const out = [];
      for (const [a, b] of polySegments(e)) {
        out.push({ x: a.x, y: a.y, kind: "end" });
        out.push({ x: (a.x + b.x) / 2, y: (a.y + b.y) / 2, kind: "mid" });
      }
      out.push({ x: e.x + e.w / 2, y: e.y + e.h / 2, kind: "center" });
      return out;
    }
    case "circle": {
      const out = [{ x: e.cx, y: e.cy, kind: "center" }];
      for (const a of [0, Math.PI / 2, Math.PI, 3 * Math.PI / 2]) {
        out.push({ x: e.cx + e.r * Math.cos(a), y: e.cy + e.r * Math.sin(a), kind: "quad" });
      }
      return out;
    }
    case "arc": {
      const p0 = arcPoint(e, e.a0), p1 = arcPoint(e, e.a1);
      const amid = e.ccw ? e.a0 + arcSweep(e) / 2 : e.a0 - arcSweep(e) / 2;
      const pm = arcPoint(e, amid);
      return [
        { x: p0.x, y: p0.y, kind: "end" },
        { x: p1.x, y: p1.y, kind: "end" },
        { x: pm.x, y: pm.y, kind: "mid" },
        { x: e.cx, y: e.cy, kind: "center" },
      ];
    }
    case "polyline": {
      const out = e.pts.map((p) => ({ x: p.x, y: p.y, kind: "end" }));
      for (const [a, b] of polySegments(e)) {
        out.push({ x: (a.x + b.x) / 2, y: (a.y + b.y) / 2, kind: "mid" });
      }
      return out;
    }
    case "text":
      return [{ x: e.x, y: e.y, kind: "end" }];
    case "dim":
      return [
        { x: e.x1, y: e.y1, kind: "end" },
        { x: e.x2, y: e.y2, kind: "end" },
      ];
  }
  return [];
}

function translateEntity(e, dx, dy) {
  switch (e.type) {
    case "line":
    case "dim":
      e.x1 += dx; e.y1 += dy; e.x2 += dx; e.y2 += dy;
      break;
    case "rect":
    case "text":
      e.x += dx; e.y += dy;
      break;
    case "circle":
    case "arc":
      e.cx += dx; e.cy += dy;
      break;
    case "polyline":
      for (const p of e.pts) { p.x += dx; p.y += dy; }
      break;
  }
}

// ============================================================
// Undo / persistence
// ============================================================
function snapshot() { return JSON.stringify(doc); }

function mutate(fn) {
  undoStack.push(snapshot());
  if (undoStack.length > UNDO_MAX) undoStack.shift();
  redoStack.length = 0;
  fn();
  afterChange();
}

function undo() {
  if (!undoStack.length) return;
  redoStack.push(snapshot());
  doc = JSON.parse(undoStack.pop());
  selection.clear();
  afterChange();
}

function redo() {
  if (!redoStack.length) return;
  undoStack.push(snapshot());
  doc = JSON.parse(redoStack.pop());
  selection.clear();
  afterChange();
}

function afterChange() {
  try { localStorage.setItem("cad-doc", snapshot()); } catch (_) {}
  refreshLayers();
  refreshProps();
  render();
}

function loadLocal() {
  try {
    const s = localStorage.getItem("cad-doc");
    if (s) {
      doc = JSON.parse(s);
      nextId = doc.entities.reduce((m, e) => Math.max(m, e.id), 0) + 1;
    }
  } catch (_) {}
}

// ============================================================
// Snapping
// ============================================================
function gridStep() {
  // minor grid step: nice number whose screen size is >= 8 px
  const min = 8 / view.scale;
  const p = Math.pow(10, Math.floor(Math.log10(min)));
  for (const m of [1, 2, 5, 10]) if (p * m >= min) return p * m;
  return p * 10;
}

function computeSnap(world) {
  const tol = 10 / view.scale;
  if (snapObj) {
    let best = null, bestD = tol;
    for (const e of doc.entities) {
      if (!layerVisible(e.layer)) continue;
      if (drag && drag.kind === "move" && drag.ids.has(e.id)) continue;
      for (const sp of snapPoints(e)) {
        const d = dist(world, sp);
        if (d < bestD) { bestD = d; best = sp; }
      }
    }
    if (best) return best;
  }
  if (snapGrid) {
    const s = gridStep();
    return { x: Math.round(world.x / s) * s, y: Math.round(world.y / s) * s, kind: "grid" };
  }
  return null;
}

// Effective point for the current cursor: snap, then ortho lock vs `ref`.
function snappedCursor(ref) {
  let p = snapResult ? { x: snapResult.x, y: snapResult.y } : { ...cursorWorld };
  if (shiftDown && ref) {
    if (Math.abs(p.x - ref.x) > Math.abs(p.y - ref.y)) p.y = ref.y;
    else p.x = ref.x;
  }
  return p;
}

// ============================================================
// Rendering
// ============================================================
function resize() {
  const dpr = window.devicePixelRatio || 1;
  canvasW = canvas.clientWidth;
  canvasH = canvas.clientHeight;
  canvas.width = Math.round(canvasW * dpr);
  canvas.height = Math.round(canvasH * dpr);
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  render();
}

function drawGrid() {
  const s = gridStep();
  const major = s * 5;
  const x0 = s2wX(0), x1 = s2wX(canvasW);
  const y0 = s2wY(canvasH), y1 = s2wY(0);

  ctx.lineWidth = 1;
  for (let x = Math.floor(x0 / s) * s; x <= x1; x += s) {
    const isMajor = Math.abs(x / major - Math.round(x / major)) < 1e-9;
    ctx.strokeStyle = isMajor ? "#2e343b" : "#22262c";
    ctx.beginPath();
    const sx = Math.round(w2sX(x)) + 0.5;
    ctx.moveTo(sx, 0); ctx.lineTo(sx, canvasH);
    ctx.stroke();
  }
  for (let y = Math.floor(y0 / s) * s; y <= y1; y += s) {
    const isMajor = Math.abs(y / major - Math.round(y / major)) < 1e-9;
    ctx.strokeStyle = isMajor ? "#2e343b" : "#22262c";
    ctx.beginPath();
    const sy = Math.round(w2sY(y)) + 0.5;
    ctx.moveTo(0, sy); ctx.lineTo(canvasW, sy);
    ctx.stroke();
  }

  // axes
  ctx.lineWidth = 1.5;
  const ax = w2sX(0), ay = w2sY(0);
  if (ax >= 0 && ax <= canvasW) {
    ctx.strokeStyle = "#3a7d44";
    ctx.beginPath(); ctx.moveTo(ax, 0); ctx.lineTo(ax, canvasH); ctx.stroke();
  }
  if (ay >= 0 && ay <= canvasH) {
    ctx.strokeStyle = "#8a3a3a";
    ctx.beginPath(); ctx.moveTo(0, ay); ctx.lineTo(canvasW, ay); ctx.stroke();
  }
}

function pathEntity(e) {
  switch (e.type) {
    case "line":
      ctx.moveTo(w2sX(e.x1), w2sY(e.y1));
      ctx.lineTo(w2sX(e.x2), w2sY(e.y2));
      break;
    case "rect": {
      const segs = polySegments(e);
      ctx.moveTo(w2sX(segs[0][0].x), w2sY(segs[0][0].y));
      for (const [, b] of segs) ctx.lineTo(w2sX(b.x), w2sY(b.y));
      break;
    }
    case "circle":
      ctx.moveTo(w2sX(e.cx) + e.r * view.scale, w2sY(e.cy));
      ctx.arc(w2sX(e.cx), w2sY(e.cy), e.r * view.scale, 0, 2 * Math.PI);
      break;
    case "arc":
      // world y-up -> screen angles negate; world CCW appears CCW visually
      ctx.arc(w2sX(e.cx), w2sY(e.cy), e.r * view.scale, -e.a0, -e.a1, e.ccw);
      break;
    case "polyline": {
      ctx.moveTo(w2sX(e.pts[0].x), w2sY(e.pts[0].y));
      for (let i = 1; i < e.pts.length; i++) ctx.lineTo(w2sX(e.pts[i].x), w2sY(e.pts[i].y));
      if (e.closed) ctx.closePath();
      break;
    }
  }
}

function drawArrow(p, dirX, dirY) { // screen-space arrowhead at p pointing along dir
  const L = 9, W = 3.5;
  const len = Math.hypot(dirX, dirY) || 1;
  const ux = dirX / len, uy = dirY / len;
  ctx.beginPath();
  ctx.moveTo(p.x, p.y);
  ctx.lineTo(p.x - ux * L - uy * W, p.y - uy * L + ux * W);
  ctx.lineTo(p.x - ux * L + uy * W, p.y - uy * L - ux * W);
  ctx.closePath();
  ctx.fill();
}

function drawDim(e, color) {
  const g = dimGeometry(e);
  const p1 = w2s({ x: e.x1, y: e.y1 }), p2 = w2s({ x: e.x2, y: e.y2 });
  const q1 = w2s(g.q1), q2 = w2s(g.q2);

  ctx.strokeStyle = color;
  ctx.fillStyle = color;
  ctx.lineWidth = 1;

  // extension lines (slightly past the dim line)
  const ext = 6;
  for (const [a, b] of [[p1, q1], [p2, q2]]) {
    const dx = b.x - a.x, dy = b.y - a.y;
    const l = Math.hypot(dx, dy) || 1;
    ctx.beginPath();
    ctx.moveTo(a.x, a.y);
    ctx.lineTo(b.x + (dx / l) * ext, b.y + (dy / l) * ext);
    ctx.stroke();
  }

  // dimension line + arrows
  ctx.beginPath(); ctx.moveTo(q1.x, q1.y); ctx.lineTo(q2.x, q2.y); ctx.stroke();
  drawArrow(q1, q1.x - q2.x, q1.y - q2.y);
  drawArrow(q2, q2.x - q1.x, q2.y - q1.y);

  // measurement text
  const label = fmt(g.len);
  const mx = (q1.x + q2.x) / 2, my = (q1.y + q2.y) / 2;
  ctx.font = "12px Consolas, monospace";
  ctx.textAlign = "center";
  ctx.textBaseline = "bottom";
  const tw = ctx.measureText(label).width;
  ctx.fillStyle = "#1a1d21";
  ctx.fillRect(mx - tw / 2 - 3, my - 16, tw + 6, 15);
  ctx.fillStyle = color;
  ctx.fillText(label, mx, my - 3);
}

function drawEntity(e, color, lineWidth = 1.5) {
  if (e.type === "dim") { drawDim(e, color); return; }
  if (e.type === "text") {
    ctx.fillStyle = color;
    ctx.font = `${Math.max(1, e.size * view.scale)}px "Segoe UI", sans-serif`;
    ctx.textAlign = "left";
    ctx.textBaseline = "alphabetic";
    ctx.fillText(e.text, w2sX(e.x), w2sY(e.y));
    return;
  }
  ctx.strokeStyle = color;
  ctx.lineWidth = lineWidth;
  ctx.beginPath();
  pathEntity(e);
  ctx.stroke();
}

function drawSnapMarker() {
  if (!snapResult || snapResult.kind === "grid") return;
  const p = w2s(snapResult);
  ctx.strokeStyle = "#ffd24d";
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  if (snapResult.kind === "end") {
    ctx.rect(p.x - 5, p.y - 5, 10, 10);
  } else if (snapResult.kind === "mid") {
    ctx.moveTo(p.x, p.y - 6); ctx.lineTo(p.x - 6, p.y + 5); ctx.lineTo(p.x + 6, p.y + 5); ctx.closePath();
  } else { // center / quad
    ctx.arc(p.x, p.y, 5.5, 0, 2 * Math.PI);
  }
  ctx.stroke();
}

function drawPreview() {
  if (!toolPts.length) return;
  const cur = snappedCursor(toolPts[toolPts.length - 1]);
  ctx.strokeStyle = "#9bd0ff";
  ctx.lineWidth = 1;
  ctx.setLineDash([5, 4]);
  ctx.beginPath();

  const p0 = toolPts[0];
  switch (tool) {
    case "line":
      ctx.moveTo(w2sX(p0.x), w2sY(p0.y));
      ctx.lineTo(w2sX(cur.x), w2sY(cur.y));
      break;
    case "polyline":
      ctx.moveTo(w2sX(p0.x), w2sY(p0.y));
      for (let i = 1; i < toolPts.length; i++) ctx.lineTo(w2sX(toolPts[i].x), w2sY(toolPts[i].y));
      ctx.lineTo(w2sX(cur.x), w2sY(cur.y));
      break;
    case "rect":
      pathEntity({ type: "rect", x: Math.min(p0.x, cur.x), y: Math.min(p0.y, cur.y),
                   w: Math.abs(cur.x - p0.x), h: Math.abs(cur.y - p0.y) });
      break;
    case "circle":
      pathEntity({ type: "circle", cx: p0.x, cy: p0.y, r: dist(p0, cur) });
      break;
    case "arc":
      if (toolPts.length === 1) {
        ctx.moveTo(w2sX(p0.x), w2sY(p0.y));
        ctx.lineTo(w2sX(cur.x), w2sY(cur.y));
      } else {
        const a = arcFrom3Points(toolPts[0], toolPts[1], cur);
        if (a) pathEntity({ type: "arc", ...a });
        else {
          ctx.moveTo(w2sX(toolPts[0].x), w2sY(toolPts[0].y));
          ctx.lineTo(w2sX(toolPts[1].x), w2sY(toolPts[1].y));
        }
      }
      break;
    case "dim":
      if (toolPts.length === 1) {
        ctx.moveTo(w2sX(p0.x), w2sY(p0.y));
        ctx.lineTo(w2sX(cur.x), w2sY(cur.y));
      } else {
        ctx.stroke();
        ctx.setLineDash([]);
        const e = dimFromPoints(toolPts[0], toolPts[1], cur);
        drawDim(e, "#9bd0ff");
        return;
      }
      break;
  }
  ctx.stroke();
  ctx.setLineDash([]);

  // live length readout while drawing line-ish things
  if ((tool === "line" || tool === "polyline" || tool === "circle") && toolPts.length) {
    const ref = toolPts[toolPts.length - 1];
    const label = tool === "circle" ? "r=" + fmt(dist(p0, cur)) : fmt(dist(ref, cur));
    ctx.fillStyle = "#9bd0ff";
    ctx.font = "11px Consolas, monospace";
    ctx.textAlign = "left";
    ctx.textBaseline = "bottom";
    ctx.fillText(label, w2sX(cur.x) + 12, w2sY(cur.y) - 8);
  }
}

function drawSelectionGrips(e) {
  ctx.fillStyle = "#4da3ff";
  for (const sp of snapPoints(e)) {
    if (sp.kind === "quad") continue;
    const p = w2s(sp);
    ctx.fillRect(p.x - 3, p.y - 3, 6, 6);
  }
}

function render() {
  ctx.fillStyle = "#1a1d21";
  ctx.fillRect(0, 0, canvasW, canvasH);

  drawGrid();

  for (const e of doc.entities) {
    if (!layerVisible(e.layer)) continue;
    if (selection.has(e.id)) continue;
    drawEntity(e, entityColor(e));
  }
  // selected on top, highlighted
  for (const e of doc.entities) {
    if (!selection.has(e.id) || !layerVisible(e.layer)) continue;
    drawEntity(e, "#4da3ff", 2.2);
    drawSelectionGrips(e);
  }

  if (drag && drag.kind === "rubber") {
    const x = Math.min(drag.sx, drag.cx), y = Math.min(drag.sy, drag.cy);
    const w = Math.abs(drag.cx - drag.sx), h = Math.abs(drag.cy - drag.sy);
    const crossing = drag.cx < drag.sx;
    ctx.fillStyle = crossing ? "rgba(126,226,168,.08)" : "rgba(77,163,255,.08)";
    ctx.strokeStyle = crossing ? "#7ee2a8" : "#4da3ff";
    ctx.lineWidth = 1;
    ctx.setLineDash(crossing ? [4, 3] : []);
    ctx.fillRect(x, y, w, h);
    ctx.strokeRect(x + 0.5, y + 0.5, w, h);
    ctx.setLineDash([]);
  }

  drawPreview();
  drawSnapMarker();

  // crosshair at snapped position while a drawing tool is armed
  if (tool !== "select") {
    const p = snapResult ? w2s(snapResult) : w2s(cursorWorld);
    ctx.strokeStyle = "rgba(214,218,222,.5)";
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(p.x - 10, p.y); ctx.lineTo(p.x + 10, p.y);
    ctx.moveTo(p.x, p.y - 10); ctx.lineTo(p.x, p.y + 10);
    ctx.stroke();
  }
}

function fmt(v) {
  const step = gridStep();
  const decimals = Math.max(0, Math.min(6, -Math.floor(Math.log10(step)) + 1));
  return v.toFixed(decimals);
}

// ============================================================
// Tools
// ============================================================
function setTool(t) {
  tool = t;
  toolPts = [];
  document.querySelectorAll(".tool").forEach((b) => b.classList.toggle("active", b.dataset.tool === t));
  canvas.style.cursor = t === "select" ? "default" : "crosshair";
  setHint();
  render();
}

const HINTS = {
  select: "Click to select; drag to window-select; drag selection to move (Ctrl = copy)",
  line: "Click start point",
  polyline: "Click points; Enter or double-click to finish",
  rect: "Click first corner",
  circle: "Click center",
  arc: "Click arc start point",
  dim: "Click first measure point",
  text: "Click text position",
};

function setHint(msg) {
  $("hint").textContent = msg || HINTS[tool] || "";
}

function dimFromPoints(p1, p2, p3) {
  const dx = p2.x - p1.x, dy = p2.y - p1.y;
  const len = Math.hypot(dx, dy) || 1;
  const nx = -dy / len, ny = dx / len;
  const off = (p3.x - p1.x) * nx + (p3.y - p1.y) * ny;
  return { type: "dim", x1: p1.x, y1: p1.y, x2: p2.x, y2: p2.y, off };
}

function addEntity(e) {
  e.id = nextId++;
  e.layer = doc.activeLayer;
  e.color = null; // by layer
  mutate(() => doc.entities.push(e));
}

function toolClick(p) {
  switch (tool) {
    case "line":
      toolPts.push(p);
      if (toolPts.length === 2) {
        const [a, b] = toolPts;
        if (dist(a, b) > 1e-9) addEntity({ type: "line", x1: a.x, y1: a.y, x2: b.x, y2: b.y });
        toolPts = [b]; // chain
        setHint("Click next point (Esc to stop)");
      } else {
        setHint("Click end point (Shift = ortho)");
      }
      break;
    case "polyline":
      toolPts.push(p);
      setHint("Click next point; Enter/double-click to finish, Esc to cancel");
      break;
    case "rect":
      toolPts.push(p);
      if (toolPts.length === 2) {
        const [a, b] = toolPts;
        if (Math.abs(b.x - a.x) > 1e-9 && Math.abs(b.y - a.y) > 1e-9) {
          addEntity({
            type: "rect",
            x: Math.min(a.x, b.x), y: Math.min(a.y, b.y),
            w: Math.abs(b.x - a.x), h: Math.abs(b.y - a.y),
          });
        }
        toolPts = [];
        setHint(HINTS.rect);
      } else setHint("Click opposite corner");
      break;
    case "circle":
      toolPts.push(p);
      if (toolPts.length === 2) {
        const r = dist(toolPts[0], toolPts[1]);
        if (r > 1e-9) addEntity({ type: "circle", cx: toolPts[0].x, cy: toolPts[0].y, r });
        toolPts = [];
        setHint(HINTS.circle);
      } else setHint("Click a point on the circle");
      break;
    case "arc":
      toolPts.push(p);
      if (toolPts.length === 3) {
        const a = arcFrom3Points(toolPts[0], toolPts[1], toolPts[2]);
        if (a) addEntity({ type: "arc", ...a });
        toolPts = [];
        setHint(HINTS.arc);
      } else setHint(toolPts.length === 1 ? "Click arc end point" : "Click a point on the arc");
      break;
    case "dim":
      toolPts.push(p);
      if (toolPts.length === 3) {
        const e = dimFromPoints(toolPts[0], toolPts[1], toolPts[2]);
        addEntity(e);
        toolPts = [];
        setHint(HINTS.dim);
      } else setHint(toolPts.length === 1 ? "Click second measure point" : "Click to place the dimension line");
      break;
    case "text": {
      const text = window.prompt("Text:");
      if (text) {
        const size = Math.max(gridStep(), 1e-6) * 2;
        addEntity({ type: "text", x: p.x, y: p.y, text, size });
      }
      break;
    }
  }
}

function finishPolyline(close = false) {
  if (tool === "polyline" && toolPts.length >= 2) {
    addEntity({ type: "polyline", pts: toolPts.map((p) => ({ x: p.x, y: p.y })), closed: close });
  }
  toolPts = [];
  setHint();
  render();
}

function cancelTool() {
  if (toolPts.length) {
    toolPts = [];
    setHint();
  } else if (tool !== "select") {
    setTool("select");
  } else {
    selection.clear();
    refreshProps();
  }
  render();
}

// ============================================================
// Mouse input
// ============================================================
function eventPos(ev) {
  const r = canvas.getBoundingClientRect();
  return { sx: ev.clientX - r.left, sy: ev.clientY - r.top };
}

canvas.addEventListener("mousedown", (ev) => {
  const { sx, sy } = eventPos(ev);
  const world = { x: s2wX(sx), y: s2wY(sy) };

  if (ev.button === 1 || ev.button === 2 || (ev.button === 0 && spaceDown)) {
    drag = { kind: "pan", sx, sy, vx: view.x, vy: view.y, moved: false };
    ev.preventDefault();
    return;
  }
  if (ev.button !== 0) return;

  if (tool === "select") {
    const tol = 7 / view.scale;
    let hit = null;
    for (let i = doc.entities.length - 1; i >= 0; i--) {
      const e = doc.entities[i];
      if (layerVisible(e.layer) && hitTest(e, world, tol)) { hit = e; break; }
    }
    if (hit) {
      if (ev.shiftKey) {
        if (selection.has(hit.id)) selection.delete(hit.id);
        else selection.add(hit.id);
      } else if (!selection.has(hit.id)) {
        selection.clear();
        selection.add(hit.id);
      }
      drag = {
        kind: "move", ids: new Set(selection),
        startWorld: world, dx: 0, dy: 0, moved: false,
        copy: ev.ctrlKey,
        before: snapshot(),
      };
      refreshProps();
    } else {
      if (!ev.shiftKey) { selection.clear(); refreshProps(); }
      drag = { kind: "rubber", sx, sy, cx: sx, cy: sy, additive: ev.shiftKey };
    }
    render();
  } else {
    const ref = toolPts.length ? toolPts[toolPts.length - 1] : null;
    toolClick(snappedCursor(ref));
    render();
  }
});

canvas.addEventListener("mousemove", (ev) => {
  const { sx, sy } = eventPos(ev);
  shiftDown = ev.shiftKey;
  cursorWorld = { x: s2wX(sx), y: s2wY(sy) };

  if (drag && drag.kind === "pan") {
    view.x = drag.vx - (sx - drag.sx) / view.scale;
    view.y = drag.vy + (sy - drag.sy) / view.scale;
    if (Math.abs(sx - drag.sx) + Math.abs(sy - drag.sy) > 3) drag.moved = true;
    render();
    updateCoords();
    return;
  }

  snapResult = computeSnap(cursorWorld);

  if (drag && drag.kind === "move") {
    const target = snapResult ? snapResult : cursorWorld;
    let dx = target.x - drag.startWorld.x;
    let dy = target.y - drag.startWorld.y;
    if (ev.shiftKey) { if (Math.abs(dx) > Math.abs(dy)) dy = 0; else dx = 0; }
    const stepX = dx - drag.dx, stepY = dy - drag.dy;
    if (stepX || stepY) {
      for (const e of doc.entities) {
        if (drag.ids.has(e.id)) translateEntity(e, stepX, stepY);
      }
      drag.dx = dx; drag.dy = dy;
      drag.moved = true;
    }
  } else if (drag && drag.kind === "rubber") {
    drag.cx = sx; drag.cy = sy;
  }

  updateCoords();
  render();
});

window.addEventListener("mouseup", (ev) => {
  if (!drag) return;
  const d = drag;
  drag = null;

  if (d.kind === "pan") {
    // right-click without movement = Esc-like cancel
    if (ev.button === 2 && !d.moved) cancelTool();
    render();
    return;
  }

  if (d.kind === "move") {
    if (d.moved) {
      if (d.copy) {
        // restore originals, then append moved copies
        const movedCopies = doc.entities
          .filter((e) => d.ids.has(e.id))
          .map((e) => JSON.parse(JSON.stringify(e)));
        doc = JSON.parse(d.before);
        undoStack.push(d.before);
        if (undoStack.length > UNDO_MAX) undoStack.shift();
        redoStack.length = 0;
        selection.clear();
        for (const c of movedCopies) {
          c.id = nextId++;
          doc.entities.push(c);
          selection.add(c.id);
        }
        afterChange();
      } else {
        undoStack.push(d.before);
        if (undoStack.length > UNDO_MAX) undoStack.shift();
        redoStack.length = 0;
        afterChange();
      }
    }
    render();
    return;
  }

  if (d.kind === "rubber") {
    const wx1 = Math.min(s2wX(d.sx), s2wX(d.cx));
    const wx2 = Math.max(s2wX(d.sx), s2wX(d.cx));
    const wy1 = Math.min(s2wY(d.sy), s2wY(d.cy));
    const wy2 = Math.max(s2wY(d.sy), s2wY(d.cy));
    if (Math.abs(d.cx - d.sx) > 3 || Math.abs(d.cy - d.sy) > 3) {
      const crossing = d.cx < d.sx;
      if (!d.additive) selection.clear();
      for (const e of doc.entities) {
        if (!layerVisible(e.layer)) continue;
        const b = entityBBox(e);
        const inside = b.minX >= wx1 && b.maxX <= wx2 && b.minY >= wy1 && b.maxY <= wy2;
        const overlaps = b.minX <= wx2 && b.maxX >= wx1 && b.minY <= wy2 && b.maxY >= wy1;
        if (crossing ? overlaps : inside) selection.add(e.id);
      }
      refreshProps();
    }
    render();
  }
});

canvas.addEventListener("dblclick", (ev) => {
  if (tool === "polyline") {
    // the dblclick was preceded by two mousedown clicks at ~same spot; drop the duplicate
    if (toolPts.length >= 2) {
      const a = toolPts[toolPts.length - 1], b = toolPts[toolPts.length - 2];
      if (dist(a, b) < 1e-9) toolPts.pop();
    }
    finishPolyline(false);
  }
});

canvas.addEventListener("wheel", (ev) => {
  ev.preventDefault();
  const { sx, sy } = eventPos(ev);
  const factor = ev.deltaY < 0 ? 1.12 : 1 / 1.12;
  zoomAt(sx, sy, factor);
}, { passive: false });

function zoomAt(sx, sy, factor) {
  const wx = s2wX(sx), wy = s2wY(sy);
  view.scale = Math.min(1e6, Math.max(1e-6, view.scale * factor));
  view.x = wx - sx / view.scale;
  view.y = wy - (canvasH - sy) / view.scale;
  render();
}

canvas.addEventListener("contextmenu", (ev) => ev.preventDefault());

function updateCoords() {
  const p = snapResult || cursorWorld;
  $("coords").textContent = `${fmt(p.x)}, ${fmt(p.y)}`;
}

// ============================================================
// Keyboard
// ============================================================
window.addEventListener("keydown", (ev) => {
  if (ev.target.tagName === "INPUT" || ev.target.tagName === "SELECT" || ev.target.tagName === "TEXTAREA") return;

  if (ev.key === " ") { spaceDown = true; ev.preventDefault(); return; }
  if (ev.key === "Shift") { shiftDown = true; render(); return; }

  if (ev.ctrlKey || ev.metaKey) {
    const k = ev.key.toLowerCase();
    if (k === "z") { ev.preventDefault(); ev.shiftKey ? redo() : undo(); }
    else if (k === "y") { ev.preventDefault(); redo(); }
    else if (k === "s") { ev.preventDefault(); saveJSON(); }
    else if (k === "a") {
      ev.preventDefault();
      selection = new Set(doc.entities.filter((e) => layerVisible(e.layer)).map((e) => e.id));
      refreshProps(); render();
    }
    return;
  }

  switch (ev.key) {
    case "Escape": cancelTool(); break;
    case "Enter": finishPolyline(false); break;
    case "Delete":
    case "Backspace":
      if (selection.size) {
        mutate(() => { doc.entities = doc.entities.filter((e) => !selection.has(e.id)); });
        selection.clear();
        refreshProps();
      }
      break;
    case "s": case "S": setTool("select"); break;
    case "l": case "L": setTool("line"); break;
    case "p": case "P": setTool("polyline"); break;
    case "r": case "R": setTool("rect"); break;
    case "c": case "C":
      if (tool === "polyline" && toolPts.length >= 3) finishPolyline(true);
      else setTool("circle");
      break;
    case "a": case "A": setTool("arc"); break;
    case "d": case "D": setTool("dim"); break;
    case "t": case "T": setTool("text"); break;
    case "f": case "F": zoomFit(); break;
    case "g": case "G": toggleSnap("grid"); break;
    case "o": case "O": toggleSnap("obj"); break;
    case "?": $("help").hidden = !$("help").hidden; break;
  }
});

window.addEventListener("keyup", (ev) => {
  if (ev.key === " ") spaceDown = false;
  if (ev.key === "Shift") { shiftDown = false; render(); }
});

function toggleSnap(which) {
  if (which === "grid") snapGrid = !snapGrid;
  else snapObj = !snapObj;
  $("togGrid").classList.toggle("on", snapGrid);
  $("togOsnap").classList.toggle("on", snapObj);
  render();
}

// ============================================================
// View commands
// ============================================================
function zoomFit() {
  if (!doc.entities.length) {
    view.scale = 40;
    view.x = -canvasW / 2 / view.scale;
    view.y = -canvasH / 2 / view.scale;
    render();
    return;
  }
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
  for (const e of doc.entities) {
    const b = entityBBox(e);
    minX = Math.min(minX, b.minX); minY = Math.min(minY, b.minY);
    maxX = Math.max(maxX, b.maxX); maxY = Math.max(maxY, b.maxY);
  }
  const w = Math.max(maxX - minX, 1e-6), h = Math.max(maxY - minY, 1e-6);
  view.scale = Math.min(canvasW / w, canvasH / h) * 0.85;
  view.x = (minX + maxX) / 2 - canvasW / 2 / view.scale;
  view.y = (minY + maxY) / 2 - canvasH / 2 / view.scale;
  render();
}

// ============================================================
// Layers UI
// ============================================================
function refreshLayers() {
  const list = $("layerList");
  list.innerHTML = "";
  for (const layer of doc.layers) {
    const row = document.createElement("div");
    row.className = "layer-row" + (layer.name === doc.activeLayer ? " active" : "");

    const vis = document.createElement("span");
    vis.className = "vis" + (layer.visible ? "" : " off");
    vis.textContent = "\u{1F441}";
    vis.title = "Toggle visibility";
    vis.onclick = (ev) => {
      ev.stopPropagation();
      mutate(() => { layer.visible = !layer.visible; });
    };

    const color = document.createElement("input");
    color.type = "color";
    color.value = layer.color;
    color.title = "Layer color";
    color.onclick = (ev) => ev.stopPropagation();
    color.onchange = () => mutate(() => { layer.color = color.value; });

    const name = document.createElement("span");
    name.className = "lname";
    name.textContent = layer.name;

    row.append(vis, color, name);

    if (doc.layers.length > 1) {
      const del = document.createElement("button");
      del.className = "del";
      del.textContent = "×";
      del.title = "Delete layer and its entities";
      del.onclick = (ev) => {
        ev.stopPropagation();
        if (!confirm(`Delete layer "${layer.name}" and all its entities?`)) return;
        mutate(() => {
          doc.entities = doc.entities.filter((e) => e.layer !== layer.name);
          doc.layers = doc.layers.filter((l) => l !== layer);
          if (doc.activeLayer === layer.name) doc.activeLayer = doc.layers[0].name;
        });
      };
      row.append(del);
    }

    row.onclick = () => {
      doc.activeLayer = layer.name;
      refreshLayers();
    };
    list.append(row);
  }
}

$("btnAddLayer").onclick = () => {
  const name = window.prompt("Layer name:");
  if (!name) return;
  if (doc.layers.some((l) => l.name === name)) { alert("Layer already exists."); return; }
  mutate(() => {
    doc.layers.push({ name, color: "#7ee2a8", visible: true });
    doc.activeLayer = name;
  });
};

// ============================================================
// Properties UI
// ============================================================
function refreshProps() {
  const box = $("props");
  box.innerHTML = "";

  if (!selection.size) {
    box.innerHTML = '<p class="dim-text">Nothing selected</p>';
    return;
  }

  const selected = doc.entities.filter((e) => selection.has(e.id));

  const info = document.createElement("p");
  info.className = "dim-text";
  info.textContent = selected.length === 1
    ? selected[0].type
    : `${selected.length} entities`;
  box.append(info);

  // layer
  addPropRow(box, "Layer", () => {
    const sel = document.createElement("select");
    for (const l of doc.layers) {
      const o = document.createElement("option");
      o.value = o.textContent = l.name;
      sel.append(o);
    }
    const same = selected.every((e) => e.layer === selected[0].layer);
    sel.value = same ? selected[0].layer : doc.layers[0].name;
    sel.onchange = () => mutate(() => selected.forEach((e) => { e.layer = sel.value; }));
    return sel;
  });

  // color
  addPropRow(box, "Color", () => {
    const inp = document.createElement("input");
    inp.type = "color";
    inp.value = selected[0].color || entityColor(selected[0]);
    inp.onchange = () => mutate(() => selected.forEach((e) => { e.color = inp.value; }));
    return inp;
  });

  if (selected.length === 1) {
    const e = selected[0];
    if (e.type === "circle") {
      addNumProp(box, "Radius", e.r, (v) => { if (v > 0) mutate(() => { e.r = v; }); });
    }
    if (e.type === "line") {
      const p = document.createElement("p");
      p.className = "dim-text";
      p.textContent = "Length: " + fmt(Math.hypot(e.x2 - e.x1, e.y2 - e.y1));
      box.append(p);
    }
    if (e.type === "text") {
      addPropRow(box, "Text", () => {
        const inp = document.createElement("input");
        inp.type = "text";
        inp.value = e.text;
        inp.onchange = () => { if (inp.value) mutate(() => { e.text = inp.value; }); };
        return inp;
      });
      addNumProp(box, "Size", e.size, (v) => { if (v > 0) mutate(() => { e.size = v; }); });
    }
  }
}

function addPropRow(box, label, makeInput) {
  const row = document.createElement("div");
  row.className = "prow";
  const lab = document.createElement("label");
  lab.textContent = label;
  row.append(lab, makeInput());
  box.append(row);
}

function addNumProp(box, label, value, onChange) {
  addPropRow(box, label, () => {
    const inp = document.createElement("input");
    inp.type = "number";
    inp.step = "any";
    inp.value = +value.toFixed(6);
    inp.onchange = () => {
      const v = parseFloat(inp.value);
      if (!isNaN(v)) onChange(v);
    };
    return inp;
  });
}

// ============================================================
// File operations
// ============================================================
function download(filename, text, mime = "text/plain") {
  const blob = new Blob([text], { type: mime });
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob);
  a.download = filename;
  a.click();
  URL.revokeObjectURL(a.href);
}

function saveJSON() {
  download("drawing.json", JSON.stringify({ version: 1, ...doc }, null, 2), "application/json");
}

$("btnNew").onclick = () => {
  if (doc.entities.length && !confirm("Start a new drawing? Unsaved work is kept in undo history.")) return;
  mutate(() => {
    doc.layers = [{ name: "0", color: "#d6dade", visible: true }];
    doc.activeLayer = "0";
    doc.entities = [];
  });
  selection.clear();
  refreshProps();
};

$("btnOpen").onclick = () => $("fileInput").click();
$("fileInput").onchange = (ev) => {
  const file = ev.target.files[0];
  ev.target.value = "";
  if (!file) return;
  const reader = new FileReader();
  reader.onload = () => {
    try {
      const data = JSON.parse(reader.result);
      if (!Array.isArray(data.entities) || !Array.isArray(data.layers)) throw new Error("bad format");
      mutate(() => {
        doc.layers = data.layers;
        doc.activeLayer = data.activeLayer || data.layers[0].name;
        doc.entities = data.entities;
      });
      nextId = doc.entities.reduce((m, e) => Math.max(m, e.id || 0), 0) + 1;
      selection.clear();
      zoomFit();
    } catch (err) {
      alert("Could not open file: " + err.message);
    }
  };
  reader.readAsText(file);
};

