// ============================================================
// SVG export
// ============================================================
function exportSVG() {
  if (!doc.entities.length) { alert("Nothing to export."); return; }
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
  for (const e of doc.entities) {
    if (!layerVisible(e.layer)) continue;
    const b = entityBBox(e);
    minX = Math.min(minX, b.minX); minY = Math.min(minY, b.minY);
    maxX = Math.max(maxX, b.maxX); maxY = Math.max(maxY, b.maxY);
  }
  const pad = Math.max(maxX - minX, maxY - minY) * 0.05 + 1;
  minX -= pad; minY -= pad; maxX += pad; maxY += pad;
  // SVG y-down: emit (x, -y), viewBox uses -maxY..-minY
  const W = maxX - minX, H = maxY - minY;
  const sw = Math.max(W, H) / 400; // hairline-ish stroke

  const Y = (y) => -y;
  const parts = [];
  parts.push(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="${minX} ${Y(maxY)} ${W} ${H}" stroke-linecap="round" fill="none">`);

  for (const e of doc.entities) {
    if (!layerVisible(e.layer)) continue;
    const c = entityColor(e);
    const attrs = `stroke="${c}" stroke-width="${sw}"`;
    switch (e.type) {
      case "line":
        parts.push(`<line x1="${e.x1}" y1="${Y(e.y1)}" x2="${e.x2}" y2="${Y(e.y2)}" ${attrs}/>`);
        break;
      case "rect":
        parts.push(`<rect x="${e.x}" y="${Y(e.y + e.h)}" width="${e.w}" height="${e.h}" ${attrs}/>`);
        break;
      case "circle":
        parts.push(`<circle cx="${e.cx}" cy="${Y(e.cy)}" r="${e.r}" ${attrs}/>`);
        break;
      case "arc": {
        const p0 = arcPoint(e, e.a0), p1 = arcPoint(e, e.a1);
        const sweep = arcSweep(e);
        const large = sweep > Math.PI ? 1 : 0;
        // world CCW -> SVG (y-down) sweep flag 0
        const sf = e.ccw ? 0 : 1;
        parts.push(`<path d="M ${p0.x} ${Y(p0.y)} A ${e.r} ${e.r} 0 ${large} ${sf} ${p1.x} ${Y(p1.y)}" ${attrs}/>`);
        break;
      }
      case "polyline": {
        const pts = e.pts.map((p) => `${p.x},${Y(p.y)}`).join(" ");
        parts.push(`<${e.closed ? "polygon" : "polyline"} points="${pts}" ${attrs}/>`);
        break;
      }
      case "text":
        parts.push(`<text x="${e.x}" y="${Y(e.y)}" font-size="${e.size}" fill="${c}" stroke="none" font-family="sans-serif">${escapeXML(e.text)}</text>`);
        break;
      case "dim": {
        const g = dimGeometry(e);
        parts.push(`<line x1="${e.x1}" y1="${Y(e.y1)}" x2="${g.q1.x}" y2="${Y(g.q1.y)}" ${attrs}/>`);
        parts.push(`<line x1="${e.x2}" y1="${Y(e.y2)}" x2="${g.q2.x}" y2="${Y(g.q2.y)}" ${attrs}/>`);
        parts.push(`<line x1="${g.q1.x}" y1="${Y(g.q1.y)}" x2="${g.q2.x}" y2="${Y(g.q2.y)}" ${attrs}/>`);
        const mx = (g.q1.x + g.q2.x) / 2, my = (g.q1.y + g.q2.y) / 2;
        const ts = Math.max(W, H) / 60;
        parts.push(`<text x="${mx}" y="${Y(my) - ts * 0.4}" font-size="${ts}" fill="${c}" stroke="none" text-anchor="middle" font-family="sans-serif">${fmt(g.len)}</text>`);
        break;
      }
    }
  }
  parts.push("</svg>");
  download("drawing.svg", parts.join("\n"), "image/svg+xml");
}

function escapeXML(s) {
  return s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}

// ============================================================
// DXF export (R12)
// ============================================================
function exportDXF() {
  if (!doc.entities.length) { alert("Nothing to export."); return; }
  const out = [];
  const pair = (code, value) => { out.push(String(code), String(value)); };
  const deg = (rad) => (normAngle(rad) * 180) / Math.PI;

  pair(0, "SECTION"); pair(2, "ENTITIES");

  const polyline = (layer, pts, closed) => {
    pair(0, "POLYLINE"); pair(8, layer); pair(66, 1); pair(70, closed ? 1 : 0);
    for (const p of pts) {
      pair(0, "VERTEX"); pair(8, layer);
      pair(10, p.x); pair(20, p.y); pair(30, 0);
    }
    pair(0, "SEQEND");
  };

  for (const e of doc.entities) {
    if (!layerVisible(e.layer)) continue;
    const L = e.layer;
    switch (e.type) {
      case "line":
        pair(0, "LINE"); pair(8, L);
        pair(10, e.x1); pair(20, e.y1); pair(30, 0);
        pair(11, e.x2); pair(21, e.y2); pair(31, 0);
        break;
      case "rect":
        polyline(L, polySegments(e).map(([a]) => a), true);
        break;
      case "circle":
        pair(0, "CIRCLE"); pair(8, L);
        pair(10, e.cx); pair(20, e.cy); pair(30, 0); pair(40, e.r);
        break;
      case "arc": {
        // DXF arcs are always CCW from angle 50 to 51
        const start = e.ccw ? e.a0 : e.a1;
        const end = e.ccw ? e.a1 : e.a0;
        pair(0, "ARC"); pair(8, L);
        pair(10, e.cx); pair(20, e.cy); pair(30, 0); pair(40, e.r);
        pair(50, deg(start)); pair(51, deg(end));
        break;
      }
      case "polyline":
        polyline(L, e.pts, !!e.closed);
        break;
      case "text":
        pair(0, "TEXT"); pair(8, L);
        pair(10, e.x); pair(20, e.y); pair(30, 0);
        pair(40, e.size); pair(1, e.text);
        break;
      case "dim": {
        // export as plain geometry: extension lines + dim line + text
        const g = dimGeometry(e);
        pair(0, "LINE"); pair(8, L); pair(10, e.x1); pair(20, e.y1); pair(30, 0); pair(11, g.q1.x); pair(21, g.q1.y); pair(31, 0);
        pair(0, "LINE"); pair(8, L); pair(10, e.x2); pair(20, e.y2); pair(30, 0); pair(11, g.q2.x); pair(21, g.q2.y); pair(31, 0);
        pair(0, "LINE"); pair(8, L); pair(10, g.q1.x); pair(20, g.q1.y); pair(30, 0); pair(11, g.q2.x); pair(21, g.q2.y); pair(31, 0);
        const mx = (g.q1.x + g.q2.x) / 2, my = (g.q1.y + g.q2.y) / 2;
        pair(0, "TEXT"); pair(8, L);
        pair(10, mx); pair(20, my); pair(30, 0);
        pair(40, g.len / 20); pair(1, fmt(g.len));
        break;
      }
    }
  }

  pair(0, "ENDSEC"); pair(0, "EOF");
  download("drawing.dxf", out.join("\r\n") + "\r\n", "application/dxf");
}

$("btnSvg").onclick = exportSVG;
$("btnDxf").onclick = exportDXF;

